UPDATE `quest_template_locale` SET `Details` = '' WHERE `ID` = 9898 AND `locale` = 'itIT' AND `Details` = 'Sarà mia. Oh sì, sarà mia.$B$BNon è forse Magasha la troll più bella che tu abbia mai visto? Devo trovare il modo di conquistare il suo cuore. Certo, lei ha gli occhi puntati su Zurai, ma le cose stanno per cambiare. Ci penserà il mio piano infallibile.$B$BTutto ciò che mi serve è un modo per dimostrare le mie abilità superiori nella caccia, ed è qui che entri in gioco tu, $gamico mio:amica mia;. C''è una gigantesca vespa di palude, nota come Spinanera, che si aggira nell''area a sud delle torri luminose dei Draenei a ovest. Portami il suo pungiglione e farò la mia magia.';
UPDATE `quest_template_locale` SET `Details` = '' WHERE `ID` = 10519 AND `locale` = 'itIT' AND `Details` = '<Oronok si raddrizza e si erge in tutta la sua altezza.>$B$BDovevo esserne certo, $N. E per esserne certo, dovevo metterti alla prova. Scusa la mia piccola messinscena. Sono un contadino quanto tu sei $guna femmina:un maschio;. Il che significa che non lo sono.$B$BSe vuoi recuperare il Cifrario della Dannazione, dovrai ascoltare quanto ho da dirti. Quando vorrai, torna da me e ti racconterò la storia.';
