UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 543 AND `locale` = 'itIT' AND `RewardText` = 'Ah, splendido. Naturalmente andrà ripulito, ma hai compiuto una vera impresa, $N. Darò immediate disposizioni che il Diadema venga sistemato e aggiunto alla nostra collezione.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 997 AND `locale` = 'itIT' AND `RewardText` = 'Ah, ecco qui! È parecchio che aspettavo questa terra rara. Spero sia ancora fresca...$B$BGrazie per avermela portata, $N. Sei davvero disponibile.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 1468 AND `locale` = 'itIT' AND `RewardText` = 'Mmm... Salve. Mi chiamo Randis. Sei tu che devi accompagnarmi? Sei un avventuriero... proprio come lo erano mia madre e mio padre.$B$BSpero che insieme ci divertiremo. Ci sono delle cose che mi piacerebbe fare e la Matrona mi ha detto che per me sarai come un $gfratello:sorella; maggiore per tutta la settimana. La cosa mi piace un sacco!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 2951 AND `locale` = 'itIT' AND `RewardText` = '<Inserisci l''Oggetto Sudicio e tre monete d''argento nella Lavatutto 5200. La macchina si mette in moto nel tentativo di eliminare lo sporco dall''oggetto sconosciuto. Dall''interno provengono violenti rumori e il telaio in metallo cigola mentre la macchina saltella da una parte all''altra...>';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 4295 AND `locale` = 'itIT' AND `RewardText` = 'Cos''è? Ah! L''odore è quello della birra dei Ferroscuro! Bere rende meno lucidi, ma una cosa è certa: tu, $gcaro signore:cara signora;, sei $gun vero amico:una vera amica;!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 4601 AND `locale` = 'itIT' AND `RewardText` = '<Inserisci l''Oggetto Sudicio e tre monete d''argento nella Lavatutto 5200. La macchina si mette in moto nel tentativo di eliminare lo sporco dall''oggetto sconosciuto. Dall''interno provengono violenti rumori e il telaio in metallo cigola mentre la macchina saltella da una parte all''altra...>';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 6362 AND `locale` = 'itIT' AND `RewardText` = 'Ah, un nuovo mucchio di pelli. Le lavorerò subito!$B$BGrazie, $Gfratello:sorella;. Mi hai reso un grande servigio. Ecco alcune monete per ripagarti del tempo e dei costi di viaggio.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 8355 AND `locale` = 'itIT' AND `RewardText` = 'Incredibile! Ben fatto, $N! Ecco il dolcetto.$B$BFelice Veglia delle Ombre!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 8479 AND `locale` = 'itIT' AND `RewardText` = 'Bel lavoro, cumpà. Zul''marosh se l''è meritata. Ha bruciato il villaggio di Ven''jashi. Ho acciso parecchi Amani prima che mi rinchiudesse in chesta gabbia. Tenevo na cosa nascosta nella sabbia... mo'' è tua.$B$BAh... il veleno... sta entrando in circolo, cumpà. È ora di schiattare...';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 8628 AND `locale` = 'itIT' AND `RewardText` = 'Dai materiali che mi hai portato e dalle scaglie dei nemici Qiraji caduti, ti realizzerò questi spallacci, mortale. Possano essi garantirti la protezione di cui necessiti e possa la loro vista incutere terrore nei nostri nemici.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 8801 AND `locale` = 'itIT' AND `RewardText` = 'Lasceremo questo luogo non appena saremo certi che il male che esso conteneva sia stato completamente distrutto. Il tuo percorso leggendario è quasi giunto al termine.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 8870 AND `locale` = 'itIT' AND `RewardText` = 'Benvenuto, $N. Vuoi partecipare ai festeggiamenti?';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 8884 AND `locale` = 'itIT' AND `RewardText` = 'A giudicare dalla puzza, mi hai portato le teste che ti ho chiesto, e forse anche qualcuna in più. Sono sicuro che troveremo un modo per usarle, magari per preparare uno stufato o qualcosa del genere.$B$BPurtroppo, nonostante i tuoi sforzi i Murloc non ne vogliono sapere di andarsene. Dobbiamo adottare una strategia più diretta!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9280 AND `locale` = 'itIT' AND `RewardText` = 'Il fatto che quelle creature abbiano dovuto dare la loro vita per la nostra non mi rende felice: uccidere creature innocenti non è da draenei. Tuttavia il loro sangue rigenererà i cristalli curativi, quindi la loro morte non sarà stata vana.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9283 AND `locale` = 'itIT' AND `RewardText` = 'La Luce sia lodata! Hai fatto ciò che solo $gun vero eroe:una vera eroina; avrebbe potuto fare! Il draenei da te salvato deve la sua vita al tuo altruismo!$B$BTi prego, prendi questa sacca. Contiene scorte di cui, al momento, tu hai più bisogno di me.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9324 AND `locale` = 'itIT' AND `RewardText` = 'E questa cos''è? Se non sbaglio, si tratta di una fiamma rubata dal cuore stesso di Orgrimmar! Mentre brucia, emana il calore dei cuori ardenti di Orchi e Troll. Davvero una splendida aggiunta alla nostra collezione. Sei stato molto coraggioso a entrare nella tana del nemico per recuperare questa fiamma sacra!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9325 AND `locale` = 'itIT' AND `RewardText` = 'Se non sbaglio, questa fiamma è stata presa tra i dirupi di Picco del Tuono! Senti come risuona del potere degli spiriti! $N, sei proprio un grande ladro! Accetta questa ricompensa, te la sei meritata. Se solo avessimo le fiamme di tutte e tre le città...';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9326 AND `locale` = 'itIT' AND `RewardText` = 'Uhm... Che strana fiamma! È leggera, quasi impercettibile, eppure il suo calore è molto intenso. L''hai presa a Sepulcra? Affascinante! Chissà cosa potremmo ottenere, se possedessimo le fiamme di tutte e tre le città?';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9628 AND `locale` = 'itIT' AND `RewardText` = '<Racconti all''Araldo Mikolaas quanto accaduto alla sua squadra. Prende in mano il cristallo con i dati, ma rimane in silenzio per qualche tempo.>$B$BErano dei bravi uomini e sapevano che la loro missione sarebbe stata pericolosa. Ti sono grato per aver localizzato la squadra e recuperato il cristallo.$B$B<I pugni dell''Araldo si stringono.>$B$BAbbiamo già perso troppi bravi uomini, e la nostra missione è appena iniziata.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9693 AND `locale` = 'itIT' AND `RewardText` = 'Ah, $N... ho sentito parlare di te. Sei $gstato:stata; tu a percorrere la Rotta di Kessel in meno di quindici minuti, vero? No? Bah.$B$BA ogni modo, sei $gpronto:pronta; a versare il sangue nemico in nome della Luce? Per Velen? Per Argus?$B$B<Boros ride.>$B$BD''accordo, ricominciamo con un po'' più di calma.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9790 AND `locale` = 'itIT' AND `RewardText` = 'Grazie, $N.$B$B<Haalrun sorride con aria comprensiva.>$B$BAlmeno non ti toccherà pulirle. È il lavoro peggiore, ma una volta fatto è praticamente impossibile capire che stavano attaccate a degli insettoni giganti.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9791 AND `locale` = 'itIT' AND `RewardText` = 'Grazie dell''aiuto con quegli Squartatori Zannamarcia, $N. Se hanno un minimo di cervello, avranno capito che è meglio vivere e lasciare vivere.$B$B<Noraani scrolla le spalle.>$B$BInsetti giganti intelligenti. Chissà cosa verrebbe fuori...';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9848 AND `locale` = 'itIT' AND `RewardText` = '<Timothy sfoglia il manuale.>$B$BUsano il velorotto come base per il veleno? No, non può essere. Il velorotto non ha proprietà tossiche.$B$BMettere del velorotto in un veleno è come dare due mazze a un ladro. Lo puoi fare, ma non otterrai granché! Non riesco a capire...$B$B<Timothy si schiarisce la gola.>$B$BVoglio dire, grazie per avermi portato questo materiale. Appena avrò tempo, eseguirò delle prove con il veleno.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9858 AND `locale` = 'itIT' AND `RewardText` = '<Tossisce>, <Tossisce>... $N! Ce l''hai fatta. Resta solo...<Tossisce>... una cosa da...<Tossisce>... fare, allora.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9896 AND `locale` = 'itIT' AND `RewardText` = 'Non so come ringraziarti, $gragazzo:ragazza;. Mi divertirò parecchio con questo...';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9898 AND `locale` = 'itIT' AND `RewardText` = 'Fantastico! Non dimenticherò mai come mi hai aiutato a conquistare il suo cuore. Anzi, puoi essere l''ospite d''onore al nostro matrimonio.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9920 AND `locale` = 'itIT' AND `RewardText` = 'Quindi, una nuova tribù di Ogre sta spingendo sempre più a sud i Rocciadura. È un problema. Dobbiamo occuparci come prima cosa della minaccia più vicina a casa...';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10184 AND `locale` = 'itIT' AND `RewardText` = 'Non meritavano questo, ma è quanto di meglio possiamo fare.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10193 AND `locale` = 'itIT' AND `RewardText` = 'Sei $gun tipo:una tipa; davvero affidabile, $N. Se c''è una cosa che mi piace più di uccidere i leccapiedi di Kael, è che qualcun altro lo faccia al posto mio.$B$BCosì avrò meno sangue sui vestiti.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10209 AND `locale` = 'itIT' AND `RewardText` = '<Non capisci se si tratti di una distorsione d''immagine o meno, ma l''Arcimago sembra sorridere.>$B$BOra che ho riavuto l''ultimo dei miei averi, possiedo tutto il necessario per spezzare l''incantesimo di Kael''thas. Comincerò subito a occuparmene.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10233 AND `locale` = 'itIT' AND `RewardText` = 'Raramente il Kirin Tor ricorre alla distruzione fine a se stessa, ma non abbiamo scrupoli nei confronti dei nostri nemici. Nemmeno dopo la morte.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10239 AND `locale` = 'itIT' AND `RewardText` = 'Non credo di aver mai visto nulla di simile. C''è parecchia energia in sospensione qui dentro, ma è in forma grezza. Dovremo fare molta attenzione nell''usarla, ma credo che riusciremo a trovare un modo per adattarla in modo che ci aiuti a tenere lontane le creature di mana.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10247 AND `locale` = 'itIT' AND `RewardText` = 'Bene, bene, a quanto pare siamo fortunati, $ggiovanotto:signorina;.$B$BHo appena finito di costruire la mia ultima invenzione, il Razziascorie X6000!$B$BE tu avrai l''onore di aiutarmi a collaudarlo, così potrà essere usato per la difesa dell''Area 52!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10248 AND `locale` = 'itIT' AND `RewardText` = 'Be'', $gragazzo mio:ragazza mia;, è stato di sicuro emozionante! E, a parer mio, direi che il Razziascorie X6000 si è comportato egregiamente, nonostante il pilota principiante.$B$BEhi, no, non offenderti, stavo solo scherzando. Dopotutto, hai appena salvato l''Area 52 e il Razzo Fatuo X-52 da una rovina certa!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10254 AND `locale` = 'itIT' AND `RewardText` = 'Salve, $gfratello:sorella;. Sono felice di vederti. Io sono Danath, capo dei Figli di Lothar e Comandante delle Forze in questo forte.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10255 AND `locale` = 'itIT' AND `RewardText` = '<Gli occhi di Thiah Chioma Rossa si spalancano, mentre riferisci i risultati dell''esperimento.>$B$BMa... come è potuto accadere?!? Sono sicura di aver preparato l''antidoto come si deve!$B$BHa funzionato con Ragni e Serpenti Venefici, perché stavolta ha fallito? Forse è una delle tante stranezze delle Terre Esterne, $N. Devo riferire quest''informazione ai miei compagni.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10256 AND `locale` = 'itIT' AND `RewardText` = 'Il Comandante Sarannis hai detto? Mmm...$B$BÈ una dei Consiglieri di Kael''thas, ma non è una Maga. Mi ricordo di lei durante l''attacco a Kirin''Var. Credo che le tue impressioni siano esatte, $N. Non è lei a sostenere personalmente la maledizione, ma possiede la chiave per spezzarla.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10257 AND `locale` = 'itIT' AND `RewardText` = 'Incredibile! Da quel poco che ho scoperto del fato di Farahlon, non sono certo di voler uscire... Ma sarà comunque meglio che restare intrappolato qui fino alla fine dei miei giorni.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10281 AND `locale` = 'itIT' AND `RewardText` = 'Mi chiamo Tyrygosa, della stirpe di Malygos, ma mi chiamano tutti Tyri. Il mio compagno è il $c Jorad Mace.$B$BLa notizia di questa strana specie di draghi si è diffusa ovunque e temo che in troppi correranno qui per sfruttarli a fine di lucro senza rendersi conto della vera natura di quello con cui hanno a che fare. Con il tuo aiuto, speriamo di comprendere queste creature prima che altri scoprano la loro presenza.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10312 AND `locale` = 'itIT' AND `RewardText` = 'Mmm...$B$BPare che avessi ragione. C''è uno schema di fondo.$B$BGli spiriti più aggressivi e pericolosi corrispondono ai membri più potenti e importanti del Kirin Tor che risiedevano nel villaggio. Gli abitanti normali e i commercianti sono del tutto trascurabili a confronto. Cosa può significare?';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10314 AND `locale` = 'itIT' AND `RewardText` = '<Il Custode Veramorte esamina i resti.>$B$BDa come hai descritto il dispositivo, direi che si tratta di un Focalizzatore Negromantico... Dovevo immaginare che quell''apprendista buono a nulla sarebbe stato disposto a qualsiasi bassezza. Pensavo che il suo addestramento gli avrebbe impedito di spingersi a tanto, ma pare che mi sbagliassi.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10337 AND `locale` = 'itIT' AND `RewardText` = 'Bessy, sei tu?$B$BGrazie per avermi riportato Bessy, $N. Non avrei potuto vivere senza di lei!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10392 AND `locale` = 'itIT' AND `RewardText` = 'Siano lodati gli Antichi, $N, ce l''hai fatta! La Legione ha subito una terribile sconfitta e Thrallmar è di nuovo salva. Se solo avessi cento guerrieri con il tuo coraggio e la tua astuzia, questa terra martoriata sarebbe già libera! Ti rendo onore.$B$B<Nazgrel ti saluta con fare deciso>';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10395 AND `locale` = 'itIT' AND `RewardText` = '$N, per fortuna hai intercettato questa missiva al momento giusto. Ci vorrà un po'' prima che io riesca a decifrarla, ma posso già percepire l''odio e l''impazienza di cui è intrisa la pergamena. Temo che le vere ragioni della presenza della Legione in questo luogo stiano per rivelarsi...$B$BDammi del tempo per decifrare le scritte.$B$B<Il Veggente Distorcente Kryv inizia a leggere la missiva demoniaca>';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10396 AND `locale` = 'itIT' AND `RewardText` = 'Devo ammetterlo, $N, sei un combattente nato! Quei bifolchi dell''Orda non sapranno mai quanto sono stati vicini a essere distrutti. Rischiare la vita per salvare i propri nemici è segno di grande carattere. Questo impegno e senso dell''onore tengono unita l''Alleanza!$B$B<Il Primo Maresciallo Brock ti saluta con fare deciso.>';
UPDATE `quest_request_items_locale` SET `CompletionText` = '' WHERE `ID` = 332 AND `locale` = 'itIT' AND `CompletionText` = 'Salute, $N. Hai provato uno dei nostri ottimi vini?';
