UPDATE `quest_request_items_locale` SET `CompletionText` = '' WHERE `ID` = 9156 AND `locale` = 'itIT' AND `CompletionText` = 'Hai qualcosa da mostrarmi?';
UPDATE `quest_request_items_locale` SET `CompletionText` = '' WHERE `ID` = 9175 AND `locale` = 'itIT' AND `CompletionText` = 'Cos''hai lì con te?';
UPDATE `quest_request_items_locale` SET `CompletionText` = '' WHERE `ID` = 9207 AND `locale` = 'itIT' AND `CompletionText` = 'Cosa posso fare per te?';
UPDATE `quest_request_items_locale` SET `CompletionText` = '' WHERE `ID` = 9512 AND `locale` = 'itIT' AND `CompletionText` = 'Arrr... Arrr... Che mi prenda un colpo... Er, scusa $gragazzo:ragazza;, devo parlare come un pirata per non dimenticare come si fa...';
UPDATE `quest_request_items_locale` SET `CompletionText` = '' WHERE `ID` = 9859 AND `locale` = 'itIT' AND `CompletionText` = 'Hai... lo zoccolo?';
