UPDATE `quest_request_items_locale` SET `CompletionText` = '' WHERE `ID` = 9927 AND `locale` = 'itIT' AND `CompletionText` = '<Lantresor spalanca gli occhi sconcertato.>Ce l''hai fatta?';
UPDATE `quest_request_items_locale` SET `CompletionText` = '' WHERE `ID` = 10166 AND `locale` = 'itIT' AND `CompletionText` = 'Sei di nuovo qui? Non hai già fatto abbastanza?';
UPDATE `quest_request_items_locale` SET `CompletionText` = '' WHERE `ID` = 10248 AND `locale` = 'itIT' AND `CompletionText` = 'Cosa ne pensi? Serve ancora qualche ritocco, eh?';
UPDATE `quest_request_items_locale` SET `CompletionText` = '' WHERE `ID` = 10457 AND `locale` = 'itIT' AND `CompletionText` = 'Come va il rafforzamento delle difese della Selva Vivente?$B$BNon conoscendo le intenzioni degli Arakkoa di Vol Lashh e avendo l''Orda a pochi passi, oltre la gola, ritengo che dobbiamo sbrigarci, o avremo serie difficoltà a difendere la nostra nuova casa e il nostro lavoro nella Selva.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9917 AND `locale` = 'itIT' AND `RewardText` = '<Bintook legge i piani.>Per la luce! Hanno una calligrafia atroce. Da quanto ho capito, intendono "mangiare i pelle blu e prendere il loro villaggio" o preparare una torta di bacche blu. Difficile dire quale delle due cose. Dobbiamo andare a fondo di questa faccenda!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 11054 AND `locale` = 'itIT' AND `RewardText` = 'Arrr! Potresti anche farcela come sovrintendente. Quella lucertola troppo cresciuta ha causato la morte di molti Orchi!$B$B<Il Gran Sovrintendente Granfango comincia a creare l''arma>.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 11131 AND `locale` = 'itIT' AND `RewardText` = 'Grazie! Che la Luce benedica le tue opere buone, $ggentile signore:dolce signora;. L''ombra del Cavaliere Senza Testa incombe ancora, ma almeno il villaggio è stato salvato dalle fiamme che ha appiccato.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 9345 AND `locale` = 'itIT' AND `RewardText` = 'Queste dovrebbero bastare. Preparerò il balsamo e completerò la stecca, poi farò ritorno a Thrallmar. Come mai ho la sensazione di sapere già ciò che dirà la Veggente Regulkut, appena mi vedrà?$B$B<Grelag sospira scoraggiato>$B$B$N, grazie per il tuo aiuto. Mi è avanzata un po'' di Fogliaspina. Prendila pure, non puoi mai sapere quando ti tornerà utile.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10596 AND `locale` = 'itIT' AND `RewardText` = 'Cosa significa che intensificheranno il bombardamento? Non possiamo permetterlo. Torna sul campo di battaglia e occupatene, finché resta ancora qualcosa del Villaggio di Torvaluna!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10597 AND `locale` = 'itIT' AND `RewardText` = 'Dovrebbe andare bene. Meglio che tu non ti faccia trovare nei paraggi quando esploderà.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10598 AND `locale` = 'itIT' AND `RewardText` = 'Non è il momento di festeggiare, $N. Non siamo ancora al sicuro. Ho nuovi ordini per te.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10660 AND `locale` = 'itIT' AND `RewardText` = 'Potrebbe volerci un po''. Accetta questo denaro come pagamento per il tuo duro lavoro.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 10760 AND `locale` = 'itIT' AND `RewardText` = 'Qui c''è ben poco di utile, a parte un paio di cose. Sembra che gli Arakkoa stessero preparando un complicato rituale magico prima di morire, ma perché? C''è anche una strana annotazione circa un "disertore".';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 11002 AND `locale` = 'itIT' AND `RewardText` = 'Questa sconfitta non è un duro colpo soltanto per Illidan. Anche la Legione vacilla! È stato sconfitto un Comandante dei Signori delle Fosse. Ormai la Legione Infuocata non ha più alcun interesse a proseguire l''assedio della Cittadella del Fuoco Infernale. Sicuramente concentrerà tutti i suoi sforzi sul Tempio Nero.$B$BPer Illidan sta arrivando il momento della redenzione... e a breve.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 11003 AND `locale` = 'itIT' AND `RewardText` = 'Questa sconfitta non è un duro colpo soltanto per Illidan. Anche la Legione vacilla! È stato sconfitto un Comandante dei Signori delle Fosse. Ormai la Legione Infuocata non ha più alcun interesse a proseguire l''assedio della Cittadella del Fuoco Infernale. Sicuramente concentrerà tutti i suoi sforzi sul Tempio Nero.$B$BPer Illidan sta arrivando il momento della redenzione... e a breve.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 11023 AND `locale` = 'itIT' AND `RewardText` = 'Eccellente, $N! Ti direi di tornare lassù a bombardarli, ma la nostra politica prevede che i piloti godano anche di turni di riposo. Mi spiace, non sono io a fare le regole, ma puoi star certo che le faccio rispettare!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 11236 AND `locale` = 'itIT' AND `RewardText` = '<Il Capitano tira un sospiro di sollievo.>$B$BBene, questo dovrebbe farci dormire sonni più tranquilli.$B$B$N, ancora una volta ti sei dimostrato un aiuto preziosissimo per il Forte di Guardia dell''Ovest e tutta l''Alleanza. Scegli una ricompensa, $gragazzo:ragazza;: è il minimo che possiamo fare per sdebitarci.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 12101 AND `locale` = 'itIT' AND `RewardText` = 'Il rozzo uomo-mucca si è procurato un Organo Resistente alla Putrefazione? Accidenti... credevo che quel compito lo avrebbe tenuto occupato per i prossimi mille anni.$B$BDai qua, $gragazzo:ragazza;. Ho già parecchio da fare senza dovermi occupare anche delle vostre patetiche necessità.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 12175 AND `locale` = 'itIT' AND `RewardText` = 'Mi hai salvato la vita, $gfratello:sorella;. Se ti interessa faticare ancora, tengo altri lavori per te.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 12521 AND `locale` = 'itIT' AND `RewardText` = 'Sì, Hemet è qui, all''accampamento: dirigiti a nord-ovest verso il fiume e lo incrocerai presto. E per l''amor della Luce, $gragazzo:ragazza;, fagli mandare qualcuno che mi tiri giù!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 12550 AND `locale` = 'itIT' AND `RewardText` = 'Penso che tu abbia trovato le prove che ci servivano su Shango. E penso anche di avere un''idea su dove trovarlo.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 12593 AND `locale` = 'itIT' AND `RewardText` = 'Cavaliere della Morte, hai sentito il richiamo del Re dei Lich. Ora è tempo di rispondere al tuo padrone.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 12636 AND `locale` = 'itIT' AND `RewardText` = 'Il momento di versare il sangue dei nostri nemici si avvicina. Prima di gettarti a capofitto nella battaglia devi conoscere ciò che stai cercando di distruggere. È questo che distingue un Cavaliere della Morte da un Ghoul Decerebrato.$B$BIo ti darò la possibilità di vedere oltre la tua vista, mio Campione. Userai l''Occhio di Acherus per rubare i segreti dei nostri nemici.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 12670 AND `locale` = 'itIT' AND `RewardText` = 'Lo senti?$B$B<Valanar annusa l''aria.>$B$BCarne fresca. L''odore di Crociato Scarlatto si diffonde nell''aria.$B$B<Valanar sbava.>$B$BTi chiedo scusa, Cavaliere della Morte, non credo ti interessino i miei gusti in cucina. So bene che sei qui per lavorare e per guidare l''assalto! Il Re dei Lich mi ha detto tutto su di te, $N.$B$BÈ giunto il tempo del massacro.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 12679 AND `locale` = 'itIT' AND `RewardText` = 'Ottimo lavoro, Cavaliere della Morte! Hai alimentato la macchina da guerra del Flagello grazie ai tuoi sforzi!$B$BAh, già, la tua ricompensa. Ecco qua, come promesso.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 12715 AND `locale` = 'itIT' AND `RewardText` = 'Salute, Cavaliere della Morte. Io sono il Signore del Sangue Keleseth, sovrano delle terre sudorientali di Nordania. Il Re dei Lich ha chiesto il mio aiuto per porre fine a questo affronto mortale verso il Flagello. Per me è un onore servirlo, anche se non mi dispiacerebbe avere a disposizione un mare infinito di anime per saziare la mia sete.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 12720 AND `locale` = 'itIT' AND `RewardText` = 'Un risveglio? Che sciocchezze vai dicendo, $gragazzo:ragazza;? Chi sarebbe così stupido da portare il proprio popolo nel cuore delle Distese Ghiacciate? Forse, però, questo corriere ha la risposta.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 12733 AND `locale` = 'itIT' AND `RewardText` = 'Gloria al vincitore, Cavaliere della Morte! Ben fatto! Il Re dei Lich ha posato il suo sguardo benevolo su di te oggi.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 12757 AND `locale` = 'itIT' AND `RewardText` = 'Cavaliere della Morte, sei diventato uno strumento di distruzione! Annienteremo gli eserciti degli invasori e creeremo un''armata di morti tutta nostra!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 12850 AND `locale` = 'itIT' AND `RewardText` = 'La guerra è cominciata, Cavaliere della Morte! Ti metterò sul mio grifone migliore che ti condurrà alla Breccia della Morte. Caos, morte, distruzione! Tu porterai tutto questo e altro!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 13121 AND `locale` = 'itIT' AND `RewardText` = 'Perfetto! Allora è vero: Iskalder è il miglior guerriero Vrykul mai esistito e sarà giudicato da Vardmadra in persona!$B$BDobbiamo sbrigarci, se vogliamo raggiungere l''Antico Eroe prima di loro!';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 13166 AND `locale` = 'itIT' AND `RewardText` = 'Ben fatto, Cavaliere della Morte. Ci occuperemo immediatamente del resto del Flagello e la ricostruzione potrà avere inizio.$B$BHo un ultimo favore da chiederti.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 13422 AND `locale` = 'itIT' AND `RewardText` = 'Il tuo esempio continua a farci da guida, $gfratello:sorella;.';
UPDATE `quest_offer_reward_locale` SET `RewardText` = '' WHERE `ID` = 24541 AND `locale` = 'itIT' AND `RewardText` = 'L''hai portata? Ottimo lavoro. Davvero eccellente. Vediamo cosa c''è qui dentro.$B$B<Rompe la cassa e fruga all''interno.>';
