UPDATE `quest_request_items_locale` SET `CompletionText` = '' WHERE `ID` = 10797 AND `locale` = 'itIT' AND `CompletionText` = 'Salve, $gragazzo mio:ragazza mia;. Che novità porti?';
UPDATE `quest_request_items_locale` SET `CompletionText` = '' WHERE `ID` = 11666 AND `locale` = 'itIT' AND `CompletionText` = 'Come va la pesca oggi, $gragazzo:ragazza;?';
UPDATE `quest_request_items_locale` SET `CompletionText` = '' WHERE `ID` = 12619 AND `locale` = 'itIT' AND `CompletionText` = 'La Lama Runica è un''estensione della tua anima. Un Cavaliere della Morte non può combattere senza di essa.';
